import{_ as i,c as a,o as e,am as t}from"./chunks/framework.1_Rjriwz.js";const m=JSON.parse('{"title":"Vilinko Studio 未成年人保护条款","description":"","frontmatter":{},"headers":[],"relativePath":"agreement/protect_child.md","filePath":"agreement/protect_child.md"}'),o={name:"agreement/protect_child.md"};function r(u,l,n,h,c,d){return e(),a("div",null,l[0]||(l[0]=[t('<h1 id="vilinko-studio-未成年人保护条款" tabindex="-1">Vilinko Studio 未成年人保护条款 <a class="header-anchor" href="#vilinko-studio-未成年人保护条款" aria-label="Permalink to &quot;Vilinko Studio 未成年人保护条款&quot;">​</a></h1><p><a href="/en/agreement/protect_child.html">【English Version】</a></p><div class="tip custom-block"><p class="custom-block-title">版本</p><p>初版发布日期：2025 年 8 月 6 日</p><p>最近更新日期：2025 年 8 月 6 日</p></div><h2 id="一、适用范围与定义" tabindex="-1">一、适用范围与定义 <a class="header-anchor" href="#一、适用范围与定义" aria-label="Permalink to &quot;一、适用范围与定义&quot;">​</a></h2><ul><li>本条款适用于所有使用 Vilinko Studio（以下简称&quot;我们&quot;）提供的互联网信息技术工具及相关服务的未成年人用户（未满18周岁的自然人）。</li><li>我们提供的服务包括但不限于用户登录系统、论坛服务、个性化定制功能、电脑桌面美化工具、文件解释器等，以及相关的网站、客户端、开源项目等。</li><li>本条款是《Vilinko Studio 软件服务协议》及<a href="./privacy.html">《隐私政策》</a>的补充条款，与上述协议具有同等法律效力。若本条款与其他协议内容不一致，优先适用本条款。</li></ul><h2 id="二、监护人责任与同意" tabindex="-1">二、监护人责任与同意 <a class="header-anchor" href="#二、监护人责任与同意" aria-label="Permalink to &quot;二、监护人责任与同意&quot;">​</a></h2><ul><li>未成年人使用我们的服务前，必须获得其法定监护人（以下简称&quot;监护人&quot;）的明确同意。监护人应仔细阅读并理解本条款及相关协议内容。</li><li>监护人有责任监督未成年人使用服务的行为，指导未成年人正确、安全地使用各项功能，包括但不限于： <ul><li>管理未成年人的账号信息，防止账号泄露或被滥用</li><li>控制未成年人在论坛发布内容的行为，避免不当言论</li><li>限制未成年人使用服务的时间，防止过度沉迷</li><li>审核未成年人上传至个性化定制功能的内容</li></ul></li></ul><h2 id="三、未成年人信息保护" tabindex="-1">三、未成年人信息保护 <a class="header-anchor" href="#三、未成年人信息保护" aria-label="Permalink to &quot;三、未成年人信息保护&quot;">​</a></h2><ul><li>我们仅在法律法规允许及提供服务所必需的范围内收集未成年人的个人信息，且必须获得监护人的同意。</li><li>收集的未成年人信息包括但不限于： <ul><li>账号注册信息（需由监护人协助完成）</li><li>服务使用记录（用于优化服务及安全保障）</li><li>监护人明确同意提供的其他信息</li></ul></li><li>我们对未成年人信息采取额外的安全保护措施，包括： <ul><li>数据加密存储及传输</li><li>限制未成年人信息的访问权限</li><li>定期安全审计及风险评估</li></ul></li><li>未经监护人明确同意，我们不会： <ul><li>向任何第三方披露未成年人的个人信息</li><li>将未成年人信息用于服务提供以外的其他目的</li><li>向未成年人推送商业广告或营销信息</li></ul></li></ul><h2 id="四、服务内容与使用限制" tabindex="-1">四、服务内容与使用限制 <a class="header-anchor" href="#四、服务内容与使用限制" aria-label="Permalink to &quot;四、服务内容与使用限制&quot;">​</a></h2><ul><li>我们对服务内容进行严格审核，确保不包含危害未成年人身心健康的信息，包括但不限于暴力、色情、赌博、毒品等内容。</li><li>对未成年人使用服务设置以下限制： <ul><li>论坛服务：未成年人发布的内容将经过额外审核，禁止发布违法违规或不适宜的内容</li><li>个性化定制功能：限制上传涉及未成年人肖像的内容分享范围</li><li>开源项目参与：未成年人参与GitHub开源项目贡献时，需由监护人协助完成身份验证</li><li>时间管理：提供使用时长提醒功能，监护人可设置每日使用上限</li></ul></li></ul><h2 id="五、开源项目知识产权特别保护" tabindex="-1">五、开源项目知识产权特别保护 <a class="header-anchor" href="#五、开源项目知识产权特别保护" aria-label="Permalink to &quot;五、开源项目知识产权特别保护&quot;">​</a></h2><ul><li>对于在GitHub上开源的部分内容，未成年人参与贡献时（包括代码提交、issue反馈等），需由监护人确认其贡献行为及内容合法性。</li><li>未成年人在开源项目中贡献的代码、文档等内容，其知识产权归未成年人所有，监护人代为行使相关权利。</li><li>我们尊重并保护未成年人在开源项目中的知识产权，任何组织或个人使用该等内容时，需遵守相关开源协议及法律法规，不得侵犯未成年人的合法权益。</li><li>如发现未成年人的知识产权在开源社区中被侵犯，我们将协助监护人采取维权措施，包括但不限于发出侵权通知、协助证据收集等。</li></ul><h2 id="六、监护人权利" tabindex="-1">六、监护人权利 <a class="header-anchor" href="#六、监护人权利" aria-label="Permalink to &quot;六、监护人权利&quot;">​</a></h2><ul><li>监护人有权查阅、更正、删除未成年人在使用服务过程中产生的个人信息及内容。</li><li>监护人有权要求我们限制或停止向未成年人提供部分或全部服务。</li><li>监护人有权注销未成年人的账号，账号注销后，我们将按照<a href="./privacy.html">《隐私政策》</a>的规定处理相关信息。</li><li>监护人对未成年人使用服务有任何疑问或异议，可随时联系我们客服进行沟通处理。</li></ul><h2 id="七、争议解决与法律适用" tabindex="-1">七、争议解决与法律适用 <a class="header-anchor" href="#七、争议解决与法律适用" aria-label="Permalink to &quot;七、争议解决与法律适用&quot;">​</a></h2><ul><li>因本条款引起的任何争议，首先由双方通过友好协商解决；协商不成的，任何一方均有权向 Vilinko Studio 所在地有管辖权的人民法院提起诉讼。</li><li>本条款的订立、效力、解释、履行及争议解决均适用中华人民共和国法律。</li></ul><h2 id="八、其他条款" tabindex="-1">八、其他条款 <a class="header-anchor" href="#八、其他条款" aria-label="Permalink to &quot;八、其他条款&quot;">​</a></h2><ul><li>我们会根据法律法规的更新及服务发展情况，对本条款进行修订。修订后的条款将在官方渠道公布，并通过适当方式通知监护人。</li><li>如对本条款有任何疑问，可通过 <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a> 与我们联系。</li></ul>',19)]))}const p=i(o,[["render",r]]);export{m as __pageData,p as default};
